using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.Architecture;

public class LayerDependencyTests
{
    private const string DomainName = "PaymentAuthorization.Domain";
    private const string ApplicationName = "PaymentAuthorization.Application";
    private const string InfrastructureName = "PaymentAuthorization.Infrastructure";

    // Allow-list of the language core business code may use. Anything else (System.IO, System.Net.*, System.Data, frameworks...) is a violation.
    private static readonly HashSet<string> CoreNamespaces =
    [
        "System",
        "System.Collections.Generic",
        "System.Linq",
        "System.Threading",
        "System.Threading.Tasks",
        "System.Runtime.CompilerServices",
        "System.Diagnostics.CodeAnalysis",
    ];

    [Fact]
    public void Domain_depends_only_on_itself_and_the_language_core() =>
        AssertOnlyDependsOn(typeof(Money).Assembly, DomainName, []);

    [Fact]
    public void Application_depends_only_on_itself_domain_and_the_language_core() =>
        AssertOnlyDependsOn(typeof(AuthorizePayment).Assembly, ApplicationName, [DomainName]);

    [Fact]
    public void Infrastructure_does_not_depend_on_anything_outside_the_inner_layers_of_this_context()
    {
        var referenced = ReferencedProjectAssemblies(typeof(FileSystemReceiptStore).Assembly);
        Assert.DoesNotContain(referenced, n => n.StartsWith("PaymentAuthorization.", StringComparison.Ordinal)
            && n is not (DomainName or ApplicationName or InfrastructureName));
    }

    private static void AssertOnlyDependsOn(Assembly assembly, string own, string[] allowedInner)
    {
        var allowedNamespaces = new HashSet<string>(CoreNamespaces) { own };
        foreach (var inner in allowedInner) allowedNamespaces.Add(inner);

        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var reader = pe.GetMetadataReader();

        var violations = new SortedSet<string>(StringComparer.Ordinal);

        foreach (var name in ReferencedProjectAssemblies(reader))
        {
            if (name != own && !allowedInner.Contains(name) && name.StartsWith("PaymentAuthorization.", StringComparison.Ordinal))
                violations.Add($"assembly {name}");
        }

        foreach (var handle in reader.TypeReferences)
        {
            var typeRef = reader.GetTypeReference(handle);
            if (typeRef.ResolutionScope.Kind == HandleKind.TypeReference) continue; // nested type; checked via its declaring type

            var ns = reader.GetString(typeRef.Namespace);
            if (!allowedNamespaces.Contains(ns))
                violations.Add($"{ns}.{reader.GetString(typeRef.Name)}");
        }

        Assert.True(violations.Count == 0, $"{own} has forbidden dependencies. Violations: {string.Join(", ", violations)}");
    }

    private static IEnumerable<string> ReferencedProjectAssemblies(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        return ReferencedProjectAssemblies(pe.GetMetadataReader()).ToList();
    }

    private static IEnumerable<string> ReferencedProjectAssemblies(MetadataReader reader) =>
        reader.AssemblyReferences.Select(h => reader.GetString(reader.GetAssemblyReference(h).Name));
}
